  忘了这是在哪里看到的一个练习题，也许对于好多人来说太简单了，自己写的时候修改了很多次才满意，感觉二分查找好像就是二叉树最早的原型吧，记录之  

二分搜索算法二分搜索算法用于针对已排序的集合进行搜索。搜索结果需要满足以下要求：1.如果有多个可匹配的值，则返回最大的那个索引。2.如果没有找到，则返回失败的位置
#include &lt;iostream&gt;#include &lt;vector&gt;//该算法无法在匹配之后提前退出template &lt;typename T&gt; std::size_t binSearch(const std::vector&lt;T&gt; &amp;vec, const T &amp;e)&#123;    std::size_t lo = 0, hi = vec.size(), mid = 0;    while (lo &lt; hi) &#123;        mid = (lo + hi) &gt;&gt; 1;        e &lt; vec[mid] ? hi = mid : lo = mid + 1;     //让lo最终定位在比所需匹配元素大一个索引的位置    &#125;    return --lo;&#125;int main(void)&#123;    std::vector&lt;int&gt; vec&#123;1, 2, 4, 4, 4, 5, 5, 5, 5, 7, 9, 10, 10, 11&#125;;    std::cout &lt;&lt; &quot;Original array:&quot; &lt;&lt; std::endl;    std::cout &lt;&lt; &quot;  Num: &quot;;    for (auto v : vec)         std::cout &lt;&lt; v &lt;&lt; &quot; &quot;;    std::cout &lt;&lt; std::endl &lt;&lt; &quot;Index: &quot;;    for (int i = 0; i &lt; vec.size(); ++i)         std::cout &lt;&lt; i &lt;&lt; &quot; &quot;;    int e, res;    std::cout &lt;&lt; std::endl &lt;&lt; &quot;Enter your number: &quot;;     while (std::cin &gt;&gt; e) &#123;        res = binSearch&lt;int&gt;(vec, e);        if (vec[res] == e)             std::cout &lt;&lt; &quot;Ok: &quot; &lt;&lt; res &lt;&lt; std::endl;        else             std::cout &lt;&lt; &quot;NO: &quot; &lt;&lt; res &lt;&lt; std::endl;        std::cout &lt;&lt; std::endl &lt;&lt; &quot;Enter your number: &quot;;     &#125;    return 0;&#125;

　　首先需要清楚数组名是数组首元素的地址，不管是一维还是多维，它是个常量，而指针是个可以存储地址的变量。使用时可以将数组名看成一个常量指针。　　C&#x2F;C++中没有内置的多维数组，多维数组是数组的数组。例如二维数组就是元素为一维数组的一维数组，此时数组名依然是数组的第一个元素的地址。具体解释看代码注释及代码的运行结果。　　C&#x2F;C++中的函数无法返回数组，所以在使用函数操作数组时，只能通过指针或者结构体等方式来间接返回数组，当然可以返回数组名，因为数组是个地址，相当于一个常量指针。具体详解可以看SOF: Return a 2d array from a function  


以下代码为了方便查看和分析，所以只是代码片段  
一维数组与指针int ar[20] = &#123;1,2,3&#125;;  //前3个元素分别是1，2，3int *p1 = ar; //将p1指向ar数组的第一个元素的地址，指向的是数组的元素，p1+1的增量为1个元素所占的字节空间int (*p2)[20] = &amp;ar; //将p2指向ar数组的地址，即指向整个数组，p2+1的增量为&amp;ar所代表的数组所占的字节空间std::cout &lt;&lt; &quot;p1+1: &quot; &lt;&lt; p1+1 &lt;&lt; &quot;\tar+1: &quot; &lt;&lt; ar+1 &lt;&lt; &quot;\t&amp;ar[1]: &quot; &lt;&lt; &amp;ar[1] &lt;&lt; std::endl;std::cout &lt;&lt; &quot;*(p1+1): &quot; &lt;&lt; *(p1+1) &lt;&lt; &quot;\t*(ar+1): &quot; &lt;&lt; *(ar+1) &lt;&lt; std::endl;std::cout &lt;&lt; &quot;*p2: &quot; &lt;&lt; *p2 &lt;&lt; &quot;\tp1: &quot; &lt;&lt; p1 &lt;&lt; &quot;\t**p2: &quot; &lt;&lt; **p2 &lt;&lt; &quot;\t*p1: &quot; &lt;&lt; *p1 &lt;&lt; std::endl;
p1是一个指向int型变量的指针，p1存储的地址与ar是一样的，都是数组第一个元素的地址，但p1是指针变量，ar是个常量地址，p1++等价于p1&#x3D;p1+1， 但不能使用ar++。下标的操作在C++中会转化为对地址的操作，如ar[i]会被转化为*(ar + i), p2是一个指针，不同于int p2[20];不加小括号时，p2会优先与后面的[20]结合，导致p2成为指针数组, 即含有20个int型指针的数组。而加了小括号p2先与结合，p2成为指针，该指针指向一个含有20个int 型元素的数组，恰好与ar数组类型相同。注意ar是一个数组，数组名表示的是该数组的第一个元素的地址。 例外情况是对数组名使用sizeof运算符将获得整个数组的大小（单位是字节）。 而对数组名取地址时，得到的将是该连续20个地址空间的首地址，虽然值相同，但意义不同。 &amp;ar[0]&#x2F;p1&#x2F;ar表示的是一个4字节的内存块的首地址，而&amp;ar却表示204个字节的内存块首地址。 相当于此时对p1&#x2F;ar加1时增加的最小单位是4个字节的连续内存空间，也就是对应第二个元素，而对&amp;ar&#x2F;p2加1是毫无意义的，增加是204个字节的连续内存空间，将会越界， 可对其解引用一次得到数组第一个元素的地址，即*p2等价于p1。  
二维数组与指针std::cout &lt;&lt; &quot;**********二维数组与指针*********&quot; &lt;&lt; std::endl;//首先C/C++中没有内置的二维数组，多维数组是都是指数组的数组，使用时很多情况下可以视为二维数组int arr[5][6] = &#123;&#123;1,2,3&#125;&#125;; //5行6列的数组，实际是一个含有5个元素的一维数组，每个元素又是一个含有6个int值的数组int (*pp1)[6] = arr;  //pp1是一个指向含有6个int元素的数组的指针int (*pp2)[5][6] = &amp;arr;  //pp2是一个指向含有5行6列的二维数组的地址，即指向的是整个数组的数组   std::cout &lt;&lt; &quot;&amp;arr[0][0]: &quot; &lt;&lt; &amp;arr[0][0] &lt;&lt; &quot;\tarr: &quot; &lt;&lt; &amp;arr &lt;&lt; &quot;\tpp1: &quot; &lt;&lt; pp1          &lt;&lt; &quot;\t*pp2: &quot; &lt;&lt; *pp2 &lt;&lt; &quot;\t**arr: &quot; &lt;&lt; **arr &lt;&lt; std::endl;//使用指针访问二维数组for (int (*pr)[6] = arr; pr != arr + 5; ++pr) &#123;    for (int *pc = *pr; pc != *pr + 6; ++pc)        std::cout &lt;&lt; *pc &lt;&lt; &quot; &quot;;    std::cout &lt;&lt; std::endl;&#125;
二维数组arr[i][j]会被解析成*((arr + i) + j)，arr依然是第一个元素的地址， 此处的第一个元素即可以表示arr[0][0]（即二维数组的第一个元素），也可以表示以行为元素的一维数组的 第一个元素(arr + 0)（即第一行的6个元素），显然这两个地址是相同的。所以对arr增加1，即移到下一个 元素的地址，下一个元素即第二行。arr的元素是含有6个int的一维数组，所以指向arr的指针类型也必须是含有 6个int的一维数组，所以*pp1的括号和后面的[6]必须要有。 pp2的解释与p2类似
函数和数组首先明确C&#x2F;C++中函数无法返回数组，所以对数组的操作和返回只能通过指针，而数组名本身就是个地址，可以看成是个常量指针以下两种方式定义一个返回二维数组的函数，实际上返回的依然是指针  
//使用typedef定义一个类型别名，该类型为一个指针，该指针指向含有6个int元素的数组//小括号不能省略，否则将成为含有6个指针的数组。由于二维数组就是数组的数组，所以该函数可以//接受一个列数为6的二维数组作为参数，并返回一个指针，该指针同样指向含有6个int元素的数组  typedef int (*Tarr)[6];Tarr func(int (*arr)[6])&#123;    return arr;&#125;
上述声明等价于
int (*func(int (*arr)[6]))[6]&#123;  return 0;&#125;int c[5][6];Tarr b = func(c);std::cout &lt;&lt; &quot;&amp;b[1][1]: &quot; &lt;&lt; &amp;b[1][1] &lt;&lt; &quot;\t&amp;c[1][1]: &quot; &lt;&lt; &amp;c[1][1] &lt;&lt; std::endl;

函数和指针这里的介绍非常详细http://www.cnblogs.com/TenosDoIt/p/3164081.htmlC语言函数指针的定义形式：返回类型 (*函数指针名称)(参数类型1, 参数类型2, 参数类型3, ...);C++语言函数指针的定义形式：返回类型 (类名称::*函数指针名称)(参数类型1, 参数类型2, 参数类型3, ...);注意，当定义指向类的成员函数的函数指针时，该成员函数如果不是静态成员函数，也必须通过类对象来调用。不能定义指向一个类对象的函数的函数指针。与C++类相关的函数指针的定义都需要使用作用域运算符::，赋值都要带取地址符&amp;，通过类对象访问需要使用.*，通过类对象指针调用成员函数指针需要使-&gt;*  
普通函数指针和类成员函数指针#include &lt;iostream&gt;void tf(char c, int i)&#123;    std::cout &lt;&lt; &quot;Normal: &quot; &lt;&lt; c &lt;&lt; i &lt;&lt; std::endl;&#125;class A &#123;public:    void func1(char c, int i)    &#123;        std::cout &lt;&lt; &quot;Class func1: &quot; &lt;&lt; c &lt;&lt; i &lt;&lt; std::endl;    &#125;    void func2(char c, int i)    &#123;        std::cout &lt;&lt; &quot;Class func2: &quot; &lt;&lt; c &lt;&lt; i &lt;&lt; std::endl;    &#125;    static void func3(char c, int i)    &#123;        std::cout &lt;&lt; &quot;Class func2: &quot; &lt;&lt; c &lt;&lt; i &lt;&lt; std::endl;    &#125;    void func4(char c, int i) const     &#123;        std::cout &lt;&lt; &quot;Class func2: &quot; &lt;&lt; c &lt;&lt; i &lt;&lt; std::endl;    &#125;&#125;;int main(void)&#123;    void (*pf)(char, int) = NULL;   //普通函数指针定义并使其指向NULL    pf = tf;    pf(&#x27;t&#x27;, 1);    void (A::*pf1)(char, int) = &amp;A::func1;  //指向类的非静态成员函数的指针，初始时必须使用取地址符    A obj_a;    (obj_a.*pf1)(&#x27;f&#x27;, 1);  //这里必须要使用括号把前面对象和函数指针名括住，且必须使用.*，而不是-&gt;//    pf = obj_a.func1;  //错误，不能让函数指针pf指向对象的指针，即使他们参数和返回值一样    A obj_b;    pf1 = &amp;A::func2;    (obj_b.*pf1)(&#x27;f&#x27;, 1);    pf = A::func3;  //静态成员可以像普通函数一样不加取地址符    pf(&#x27;f&#x27;, 3);   //因为是静态成员，所以不需要对象，可以直接通过函数指针调用    void (A::*pfc)(char, int) const = &amp;A::func4;  //const 函数的函数指针也必须带有const    A obj_c;    (obj_c.*pfc)(&#x27;c&#x27;, 4);    return 0;&#125;
输出结果：
Normal: t1Class func1: f1Class func2: f1Class func2: f3Class func2: c4

函数指针作为参数和返回值要善用typedef简化函数指针类型的定义。具体看下面的一个例子：
#include &lt;iostream&gt;int display(char c, int i)&#123;    for (int n = 0; n &lt; i; ++n)        std::cout &lt;&lt; c;    std::cout &lt;&lt; std::endl;    return i;&#125;//接受一个指向形如display的函数指针，一个char和一个int作为参数的函数//没有返回值void dfun(int (*pp)(char, int), char c, int i)&#123;    pp(c, i);&#125;//该函数与dfun函数类似，只是其返回值为指向形如display函数的函数指针int (*pdfun(int (*pd)(char, int), char c, int i))(char, int)&#123;    pd(c, i);    return pd;&#125;int main(void)&#123;    dfun(display, &#x27;d&#x27;, 6);  //调用带有函数指针作为参数的函数    int (*pd)(char, int) = pdfun(display, &#x27;p&#x27;, 7);  //调用返回值为函数指针的函数    pd(&#x27;p&#x27;, 8);  //调用函数指针的返回值的函数    //使用typedef简化函数指针类型的定义    //定义一个指向形如display的函数指针的类型pd_type    typedef int (*pd_type)(char, int);    pd_type pdd = display;    pdd(&#x27;s&#x27;, 10);    //定义一个指向形如pdfun的函数指针的类型pdfun_tye类型    typedef int (*(*pdfun_type)(pd_type, char, int))(char, int);    pdfun_type ppdfun = pdfun;    pd_type ppd = ppdfun(pdd, &#x27;u&#x27;, 12);  //调用并获取其返回的函数指针    ppd(&#x27;x&#x27;, 15);    return 0;&#125;
输出：
ddddddpppppppppppppppssssssssssuuuuuuuuuuuuxxxxxxxxxxxxxxx

函数指针数组举例说明：
#include &lt;iostream&gt;float f1(float a, int b)&#123;    std::cout &lt;&lt; a &lt;&lt; &quot; + &quot; &lt;&lt; b &lt;&lt; &quot; = &quot; &lt;&lt; a + b &lt;&lt; std::endl;    return a + b;&#125;float f2(float a, int b)&#123;    std::cout &lt;&lt; a &lt;&lt; &quot; * &quot; &lt;&lt; b &lt;&lt; &quot; = &quot; &lt;&lt; a * b &lt;&lt; std::endl;    return a * b;&#125;int main(void)&#123;    //定义并初始化函数指针数组    float (*pfa[2])(float, int) = &#123;f1, f2&#125;;    //调用该函数指针数组    for (int i = 0; i &lt; 2; ++i) &#123;        pfa[i](3, 9);    &#125;        //使用typedef简化定义    typedef float (*f_type)(float, int);    f_type pfa2[] = &#123;f1, f2&#125;;    //调用该函数指针数组    for (int i = 0; i &lt; 2; ++i) &#123;        pfa2[i](6, 8);    &#125;    return 0;&#125;
输出为：
3 + 9 = 123 * 9 = 276 + 8 = 146 * 8 = 48

位字段（bit field）也称位域，是一个由signed int 或 unsigned int中一组相邻的位 (C99 还允许 _Bool类型的位字段). 位字段由一个结构体声明建立, 该结构声明为每个字段提供标签, 并决定字段的宽度。使用位字段可以将有些仅需要很少的变量范围的值压缩到一个较小的结构体中。声明时需要在变量名后面跟冒号（:），冒号后面跟上需要设置的它的位宽度。或者在在类型名后面跟冒号再跟位宽度，用于对齐占位


如：
#include &lt;iostream&gt;struct bit_conf &#123;    unsigned int a:1;    //声明一个位宽为1位的成员变量a，也就是a只能是1或0    int b:4;        //声明一个位宽为4的成员变量b，其可表示范围为有符号的-2^2~2^2    unsigned int c:7;    unsigned int d:20;    //一个int占4个字节，32位，那么一个字节之内bit_conf中共可以有32个位                          //，所以此时sizeof(bit_conf)为4，如果将d声明为21，则sizeof(bit_conf)将为8，由于内存对齐的原因，就需要占用8个字节&#125;;int main(void)&#123;    bit_conf conf;    conf.b = -8;    //其取值只能是-8～8    std::cout &lt;&lt; conf.b &lt;&lt; std::endl;    std::cout &lt;&lt; &quot;sizeof(bit_conf):&quot; &lt;&lt; sizeof(bit_conf) &lt;&lt; std::endl;    return 0;&#125;
输出结果为：
-8sizeof(bit_conf):4
注意位域具有不可移植性，也就是说各平台之间具体特异性，不同的平台实现可能不一样。

条件编译是由一批预处理器指令，通过指定一些限定的条件，有选择性地对源代码进行预处理，从而实现条件编译。后续的编译、链接等过程都是在预处理之后的代码上进行的，所以预处理之后的代码通常要精简很多（这里精简的思想是包含那个引入的头文件的），无意义的编译指令，根据条件编译代码不需要编译的代码，还有注释都会有预处理之后忽略掉。常用的预的处理器指令主要有（方括号中为后面需要跟的内容）：


#空指令： 无意义，预处理时会被忽略#include [file_name]： 包含一个源代码文件，通常是头文件#define [args] [可选的常量]： 定义宏#undef [args]：取消已定义的宏#if [args]： 如果给定条件为真，则编译下面代码，args必须是已定义的常量宏，或者未定义#ifdef [args]：如果宏已经定义，则编译下面代码#ifndef [args]：如果宏没有定义，则编译下面代码#elif [args]：如果前面的#if给定条件不为真，当前条件为真，则编译下面代码#endif：结束一个#if……#else条件编译块#error [sentence]：停止编译并显示错误信息#line [number] [file_name]：修改变量__LINE__和__FILE__的值
注意有两个特殊的运算符：#运算符和##运算符下面以代码举例：头文件：macro.h
#ifndef MACRO_H  //防止头文件被重复包含#define MACRO_H#include &lt;iostream&gt;#   //空指令，没有任何意义#endif /* !MACRO_H */

源文件：macro.cpp
#include &quot;macro.h&quot;#define PI 3.1415926   //#define指令#define CUBE(x) (x)*(x)*(x)  //带参数的#define指令#define AGE(x) &quot;My age is &quot; #x   //#运算符用于将后面的参数转成字符串#define CON(x, y, z) x##y##z  //##运算符将其两侧的参数合并为一个符号，注意x, y, z必须为数字#define DEBUG 0#define RUN 1#define NODEBUG#define IS_COMPILE#undef IS_COMPILE   //取消宏定义int main(void)&#123;    std::cout &lt;&lt; PI &lt;&lt; std::endl;    std::cout &lt;&lt; CUBE(PI + PI) &lt;&lt; std::endl;    std::cout &lt;&lt; AGE(25) &lt;&lt; std::endl;    std::cout &lt;&lt; CON(18, 19, 20) &lt;&lt; std::endl;#if DEBUG  //#if后面必须是个常量，如果DEBUG为真，则编译其后的代码，直到#elif，或#else，或#endif    std::cout &lt;&lt; &quot;Debug&quot; &lt;&lt; std::endl;#elif RUN  //同#if，与控制语句else if作用一样    std::cout &lt;&lt; &quot;Run&quot; &lt;&lt; std::endl;#else    std::cout &lt;&lt; &quot;NONE&quot; &lt;&lt; std::endl;#endif#ifdef NODEUBG  //等价于#if defined NODEUBG    std::cout &lt;&lt; &quot;NoDebug&quot; &lt;&lt; std::endl;#endif#ifdef IS_COMPILE    std::cout &lt;&lt; &quot;is compile&quot; &lt;&lt; std::endl;#endif#ifndef NODEUBG  //等价于#if !defined NODEUBG    std::cout &lt;&lt; &quot;no NoDebug&quot; &lt;&lt; std::endl;#endif#line 15 &quot;my_macro.cpp&quot;  //更改当前行为第15行，文件名为my_macro.cpp，也就是修改__LINE__和__FILE__变量的值#if !defined(__cplusplus)   //如果没有定义__cplusplus则报错误#error+其后的字符串内容#error C++ compiler required.#endif    return 0;&#125;
上述代码通过g++ 4.8.4预处理（命令是g++ -E -std&#x3D;c++11 macro.cpp）之后的代码如下（忽略掉包含的头文件iostream部分）：
# 1 &quot;macro.cpp&quot;# 1 &quot;&lt;built-in&gt;&quot;# 1 &quot;&lt;command-line&gt;&quot;# 1 &quot;/usr/include/stdc-predef.h&quot; 1 3 4# 1 &quot;&lt;command-line&gt;&quot; 2# 1 &quot;macro.cpp&quot;# 1 &quot;macro.h&quot; 1# 10 &quot;macro.h&quot;# 1 &quot;/usr/include/c++/4.8/iostream&quot; 1 3# 36 &quot;/usr/include/c++/4.8/iostream&quot; 3       # 37 &quot;/usr/include/c++/4.8/iostream&quot; 3# 1 &quot;/usr/include/x86_64-linux-gnu/c++/4.8/bits/c++config.h&quot; 1 3# 184 &quot;/usr/include/x86_64-linux-gnu/c++/4.8/bits/c++config.h&quot; 3# 11 &quot;macro.h&quot; 2# 9 &quot;macro.cpp&quot; 2# 18 &quot;macro.cpp&quot;int main(void)&#123;    std::cout &lt;&lt; 3.1415926 &lt;&lt; std::endl;    std::cout &lt;&lt; (3.1415926 + 3.1415926)*(3.1415926 + 3.1415926)*(3.1415926 + 3.1415926) &lt;&lt; std::endl;    std::cout &lt;&lt; &quot;My age is &quot; &quot;25&quot; &lt;&lt; std::endl;    std::cout &lt;&lt; 181920 &lt;&lt; std::endl;    std::cout &lt;&lt; &quot;Run&quot; &lt;&lt; std::endl;# 38 &quot;macro.cpp&quot;    std::cout &lt;&lt; &quot;no NoDebug&quot; &lt;&lt; std::endl;# 15 &quot;my_macro.cpp&quot;    return 0;&#125;
可以看到代码中少了很多预处理器不需要处理的代码，而且里面已经没有任何预处理指令了，所有剩下的代码都是必须编译并执行的代码。而且return 0的前面一句显示出行号和文件名被#line改成了15、my_macro.cpp

深拷贝（Deep copy）和浅拷贝（Shallow copy）是指对于类或结构体这类复合类型的变量，当它们的成员变量中含有指针时，在赋值或初始化的过程中，如果只是修改指针的指向，则属于浅拷贝（也称位拷贝）。因为此时指针所指向的实际内容依然只有一份，当其中一个变量销毁时，则该内存将被释放，那么此时另一个变量中将存在悬挂指针。而如果在发生拷贝时首先将需要被拷贝的内容复制到一个新的内存地址，然后再将相应的指针指向该新地址，则称为深拷贝。SOF上的一个相关回答http://stackoverflow.com/questions/184710/what-is-the-difference-between-a-deep-copy-and-a-shallow-copy&lt;&gt;
首先提示：在C++中，对于类型class1来说，class1 a(b);等价于class1 a &#x3D; b;都将调用拷贝构造函数进行初始化，而不是将后面的语句中使用赋值运算符对a进行赋值。如果要使用赋值运算符将b赋值给a，需要class1 a; a = b;
下面举例说明：


#include &lt;iostream&gt;#include &lt;cstring&gt;//注释语句注释的是紧接着下面的语句class A &#123;public:    //指定为delete，阻止编译器合成默认的构造函数，当调用该构造函数时，将出现编译错误    //如果不指定为delete，或指定为default，则系统将合成默认的构造函数    A() = delete;      //将定义该构造函数为深拷贝构造函数，即需要将str的内容复制到一个新的内存地址中，    //而不仅仅是将成员变量指针name指向str所在的地址    A(const char *str);    //如果不定义该拷贝构造函数，则编译器会合成一个默认的拷贝构造函数    //如果不定义赋值运算符，则合成的赋值运算符将会调用该拷贝构造函数    A(const A &amp;other);    //深拷贝的拷贝构造函数，为了与上面的构造函数区分，多加一个无用的形参    A(const A &amp;other, bool unuse);    //定义为一个深拷贝的赋值运算符，也就是将other的成员变量name所指定的内存中的内容    //复制到一个新地址，并将赋值运算符左侧变量的name指向该新地址    A&amp; operator=(const A&amp; other);    ~A();private:    char *name;    bool unused;&#125;;//浅拷贝，因为当other析构时，other的成员变量name所指向的空间将被销毁//被赋值的实例变量name将成为悬挂指针A::A(const A &amp;other)  &#123;    std::cout &lt;&lt; &quot;浅拷贝的拷贝构造函数&quot; &lt;&lt; std::endl;    name = other.name;&#125;//深拷贝的构造函数，使用新的内存来存放对象other的成员变量name所指向内存的内容A::A(const A &amp;other, bool unuse)&#123;    std::cout &lt;&lt; &quot;深拷贝的拷贝构造函数&quot; &lt;&lt; std::endl;    name = new char[strlen(other.name) + 1];    strcpy(name, other.name);    unused = unuse;&#125;A::A(const char *str)&#123;    std::cout &lt;&lt; &quot;深拷贝的构造函数&quot; &lt;&lt; std::endl;    if (str != nullptr) &#123;        name = new char[strlen(str) + 1];        std::strcpy(name, str);    &#125;    else &#123;        name = new char[1];        name[0] = &#x27;\0&#x27;;    &#125;&#125;//深拷贝的赋值运算符A&amp; A::operator=(const A&amp; other)&#123;    std::cout &lt;&lt; &quot;深拷贝的赋值运算符&quot; &lt;&lt; std::endl;    if (this != &amp;other) &#123;        A to(other, true);  //调用深拷贝构造函数，以免浅拷贝导致内存泄漏        char *tn = name;        name = to.name;        to.name = tn;    &#125;    return *this;&#125;A::~A()&#123;    std::cout &lt;&lt; &quot;析构函数&quot; &lt;&lt; std::endl;    delete[] name;&#125;int main(void)&#123;    char ts[] = &quot;I love China&quot;;    A a(ts);   //深拷贝，析构时没有问题//    A b(a);  //浅拷贝的构造函数，a和b的name将指向同一块内存，所以时析构时将出错//    A c = a;  //等价于A b(a)都是调用拷贝构造函数    A d(ts);  //先定义d，再使用a赋值给d，将调用赋值运算符    d = a;  //如果没有自定义赋值运行符，将调用合成的赋值运算符，析构d时将出错    return 0;&#125;
