C&#x2F;C++中的二维数组实际上都是以一维数组为元素的一维数组，C++中可以有三种方式申请动态数组：

使用C语言中的malloc分配，free释放
使用C++中的new[]分配，delete[]释放
使用C++中的vector实现

下面分别举例说明：

/* * dynamic_2dimension_arr.cpp * Copyright (C) 2016  &lt;@BLUEYI-A0835&gt; * * Distributed under terms of the MIT license. */#include &lt;iostream&gt;#include &lt;vector&gt;//声明一个m * n的动态二维数组，使用函数返回该二维数组，并分别使用malloc和new分配空间//谨记二给数组即是数组的数组//这三个函数用于验证二维数组的使用//初始化一个二维数组void iniarr(int** arr, int m, int n)&#123;    for (int i = 0; i &lt; m; ++i)        for (int j = 0; j &lt; n; ++j)            arr[i][j] = i + j;&#125;//输出一个二维数组中的值void printarr(int** arr, int m, int n)&#123;    for (int i = 0; i &lt; m; ++i) &#123;        for (int j = 0; j &lt; n; ++j) &#123;            std::cout &lt;&lt; arr[i][j] &lt;&lt; &quot; &quot;;        &#125;        std::cout &lt;&lt; std::endl;    &#125;    std::cout &lt;&lt; std::endl;&#125;//调用上面两个函数，表示使用二维数组arrvoid usearr(int** arr, int m, int n)&#123;    iniarr(arr, m, n);    printarr(arr, m, n);&#125;//使用malloc定义二维数组，两步分配空间，分配的各维空间可能不连续int** mularr_ma(int m, int n)&#123;    //声明一个含有m个元素的一维数组，每个数组中的元素都是int*类型（即另一个一维数组）    //并分配空间，相当于二维的m行    int **arr = (int**)malloc(m * sizeof(int*));      for (int i = 0; i &lt; m; ++i)        arr[i] = (int*)malloc(n * sizeof(int));  //为一维数组中的每个指针元素申请n个int大小的空间，相当于二维中的列    return arr;&#125;//使用malloc一步分配所有第二维的空间，分配的各维空间连续int** mularr_ma2(int m, int n)&#123;    //声明一个含有m个元素的一维数组，每个数组中的元素都是int*类型（即另一个一维数组）    //并分配空间，相当于二维的m行    int **arr = (int**)malloc(m * sizeof(int*));      arr[0] = (int*)malloc(m * n * sizeof(int)); //注意arr[0]的内存很大，直接就是m*n个int的空间    for (int i = 1; i &lt; m; ++i) //让arr[1]到arr[m-1]分别指向arr[0]后面的空间        arr[i] = arr[i-1] + n;  //每次跳过0个元素    return arr;&#125;//使用new分两步分配，各列所处内存可能不连续int** mularr_new(int m, int n)&#123;    int **arr = new int*[m];  //m行    for (int i = 0; i &lt; m; ++i)        arr[i] = new int[n];  //每行n列    return arr;&#125;//使用new分配各列连续的内存，类似上面int** mularr_new2(int m, int n)&#123;    int **arr = new int*[m];  //m行    arr[0] = new int[m * n];    for (int i = 1; i &lt; m; ++i)        arr[i] = arr[i - 1] + n;    return arr;&#125;//使用vector代替二维数组//其实就是vector的vectorstd::vector&lt;std::vector&lt;int&gt;&gt; mulvec(int m, int n)&#123;    //声明一个含有m个元素的vector，每个vector使用含有n个int的vector填充    std::vector&lt;std::vector&lt;int&gt;&gt; res(m, std::vector&lt;int&gt;(n));     return res;&#125;//使用vector，为了效率，传递引用void usevec(std::vector&lt;std::vector&lt;int&gt;&gt; &amp;vec)&#123;    //可以像二维数组一样使用    //赋值    for (int i = 0; i &lt; vec.size(); ++i)         for (int j = 0; j &lt; (vec[0]).size(); ++j)            vec[i][j] = i + j;    //遍历输出    for (auto i : vec) &#123;        for (auto j : i)            std::cout &lt;&lt; j &lt;&lt; &quot; &quot;;        std::cout &lt;&lt; std::endl;    &#125;    std::cout &lt;&lt; std::endl;&#125;int main(void)&#123;    int m = 5, n = 6;    int **arr = mularr_ma(m, n);    usearr(arr, m, n);    //malloc需要使用free释放，释放时先释放每一行，再释放外层一维数组    for (int i = 0; i &lt; m; ++i)        free(arr[i]);    free(arr);    arr = mularr_ma2(m, n);    usearr(arr, m, n);    //注意此处释放只需要先释放arr[0]，再释放arr即可，不能现你上面那样释放，不然就会重复释放    free(arr[0]);    free(arr);    arr = mularr_new(m, n);    usearr(arr, m, n);    //new的数组需要使用delete[]释放    for (int i = 0; i &lt; m; ++i)  //先释放各维中的内存        delete[] arr[i];    delete[] arr; //再释放最外层这一维的内存    arr = mularr_new2(m, n);    usearr(arr, m, n);    //先释放arr[0]，再释放arr即可    delete[] arr[0];    delete[] arr; //再释放最外层这一维的内存    //使用vector代替二维数组    std::vector&lt;std::vector&lt;int&gt;&gt; varr = mulvec(m, n);    usevec(varr);    //容器不需要手动管理内存，非常棒    return 0;&#125;

对于已经确定一维的情况1.假如已知第一维为5，第二维为变量n，声明二维数组
int *a[5];  //定义一个含有5个变量的一维数组，每一个元素含有一个int*的元素//然后为每一维分配第二维的空间for (int i = 0; i &lt; 5; ++i)    a[i] = new int[n];usearr(a, 5, n);//只需释放手动分配的即可for (int i = 0; i &lt; 5; ++i)    delete[] a[i];

2.假如已知第二维为6，第一维为变量m，声明二维数组
int (*b)[6];  //声明一个指针，该指针指向数组，数组中的元素为含有6个int元素的数组b = new int[m][6];  //使用new开辟一个二维数组空间，注意这种情况下第二维必须已知usearr(b, 5, n);//当然此处使用usearr()调用肯定不行，会报类型不匹配，因为usearr的第一个参数是int**//只需释放手动分配的即可delete[] b;

CUDA程序往往很难高度，特别是核函数出错时，甚至有些情况下核函数中内容访问错误时，运行程序之后系统返回的报错信息是free() error之类的错误，会严重误导错误查找过程。所以编写CUDA程序一定记得进行错误错误处理，多写几行代码，有可能省出很多的时间。假如自己的CUDA程序出现了各种奇葩、难以理解的错误，可以考虑加上错误处理，也许就柳岸花明了。在CUDA学习笔记最后的总结中刻意提到编写CUDA程序一定要做错误处理，但其中一直未提及如何进行错误处理，这里给补上。


CUDA编程中的错误处理实际上非常简单，错误处理相关的函数一共也只有4个：

__host__ __device__ const char* cudaGetErrorName( cudaError_t error ) 接受一个错误码，返回错误名称
__host__ __device__ const char* cudaGetErrorString( cudaError_t error ) 接受一个错误码，返回错误描述
__host__ __device__ cudaError_t cudaGetLastError( void ) 返回上一次CUDA runtime调用时的错误码，并将CUDA错误码置为cudaSuccess
__host__ __device__ cudaError_t cudaPeekAtLastError( void ) 与上面功能一样，但不会重置CUDA的错误信息当核函数被调用或者CUDA API被调用时，通常都会返回一个错误码，如果返回的错误码为0，则表示该调用没有出错，即cudaSuccess（即错误名称），CUDA的错误码一共有82个（截止到2017.3.29），所有的错误码信息可以在这里查看cudaError，其实就是个enum类型的数据。

根据官方提代的4个错误处理函数，明显可以看出对于cudaMemcpy这类API调用函数，可以直接传递给cudaGetErrorString来进行错误检查，而核函数调用之后必然会更新CUDA Runtime的错误值，那么就可以在核函数调用之后调用cudaGetLastError()来进行核函数调用的错误检查。由于CPU与GPU程序时异步执行，所以为了避免获取到的核函数调用错误信息有误，应该在调用cudaGetLastError()这类函数之前使用cudaDeviceSynchronize()对CPU进行阻塞，以同步GPU与CPU的线程，保证核函数已经调用完成。为了便于错误处理，通常会将错误处理写成函数，或者进行宏定义，不然每次获取到错误码之后，都还要去调用cudaGetErrorString来查看错误描述。下面是我常用的一个错误处理宏定义，兼容C与C++，可以参考：
//API调用错误处理，可以接受CUDA的API函数调用作为参数#define CHECK_ERROR(error) checkCudaError(error, __FILE__, __LINE__)//检查CUDA Runtime状态码，可以接受一个指定的提示信息#define CHECK_STATE(msg) checkCudaState(msg, __FILE__, __LINE__)inline void checkCudaError(cudaError_t error, const char *file, const int line)&#123;   if (error != cudaSuccess) &#123;      std::cerr &lt;&lt; &quot;CUDA CALL FAILED:&quot; &lt;&lt; file &lt;&lt; &quot;( &quot; &lt;&lt; line &lt;&lt; &quot;)- &quot; &lt;&lt; cudaGetErrorString(error) &lt;&lt; std::endl;      exit(EXIT_FAILURE);   &#125;&#125;inline void checkCudaState(const char *msg, const char *file, const int line)&#123;   cudaError_t error = cudaGetLastError();   if (error != cudaSuccess) &#123;      std::cerr &lt;&lt; &quot;---&quot; &lt;&lt; msg &lt;&lt; &quot; Error---&quot; &lt;&lt; std::endl;      std::cerr &lt;&lt; file &lt;&lt; &quot;( &quot; &lt;&lt; line &lt;&lt; &quot;)- &quot; &lt;&lt; cudaGetErrorString(error) &lt;&lt; std::endl;      exit(EXIT_FAILURE);   &#125;&#125;

调用举例，下面是从以前一个项目代码中抽出来的代码片断：
//统计用于GPU计算的时间cudaEvent_t start, stop;CHECK_ERROR(cudaEventCreate(&amp;start));CHECK_ERROR(cudaEventCreate(&amp;stop));CHECK_ERROR(cudaEventRecord(start, 0));CHECK_ERROR(cudaEventSynchronize(start));CHECK_ERROR(cudaMemcpy(dev_grid_in, grid_in, SIZE * sizeof(double), cudaMemcpyHostToDevice));CHECK_ERROR(cudaMemcpy(dev_grid_out, grid_out, SIZE * sizeof(double), cudaMemcpyHostToDevice));for (int i=0; i&lt;times; ++i) &#123;   kernel&lt;&lt;&lt;grids, blocks&gt;&gt;&gt;(dev_grid_in, dev_grid_out);   std::swap(dev_grid_in, dev_grid_out);&#125;cudaDeviceSynchronize();CHECK_STATE(&quot;kernel call&quot;);CHECK_ERROR(cudaMemcpy(grid_in, dev_grid_in, SIZE * sizeof(double), cudaMemcpyDeviceToHost));//计算统计的时间CHECK_ERROR(cudaEventRecord(stop, 0));CHECK_ERROR(cudaEventSynchronize(stop));float elapsedTime;CHECK_ERROR(cudaEventElapsedTime(&amp;elapsedTime, start, stop));
